\entrytitle{7}{Travelling salesman}{strengthPolynomial}{evidencePartial}{hardwareExponential}
\setcounter{problem}{6}
\begin{problem}[Travelling salesman problem]
Given a weighted graph $G=(V,E,w)$, $|V|=n$, find a Hamiltonian cycle $C$ minimizing $\sum_{e\in C}w(e)$, or report infeasibility. Integer weights have maximum magnitude $L$ and are binary encoded. The problem models routing and cyclic sequencing.
The general quantum bound uses QRAM time and the bounded-degree bounds use quantum gate time, while classical bounds use RAM time with polynomial weight-bit costs.
\end{problem}
\speedupheading
\complexity{Quantum}{$O^*(1.728^n)$, quantum subset dynamic programming; $O^*(1.110^n)$ and $O^*(1.301^n)$ on degree-three and degree-four graphs, quantum backtracking.}
The general algorithm assumes coherent access to its exponentially large precomputed table. The bounded-degree algorithms use polynomial workspace and have additional factors $\log L\log\log L$ for integer weights. Their graph restrictions are part of the stated comparisons.
\complexity{Classical}{$O(n^2 2^n)$, Held--Karp dynamic programming; $O^*(1.1757^n)$ and $O^*(1.4214^n)$ on degree-three and degree-four graphs, sparse-graph path-decomposition algorithms.}
Held--Karp uses $O(n2^n)$ words and optimizes paths indexed by a visited set and endpoint. The sparse-graph bounds use exponential memory and the weighted connectivity algorithm of Gaspers. A polynomial-space cubic-graph comparator runs in $O^*(1.232^n)$ time. Thus each quantum bound is compared with the applicable degree and memory regime, with the bit cost of objective arithmetic retained in polynomial factors.
\dimensionlabel{Strength}{strengthPolynomial} Polynomial speedups through smaller exponential constants. General subset dynamic programming uses minimum finding and amplitude amplification; the bounded-degree constructions use quantum backtracking.
\dimensionlabel{Evidence}{evidencePartial} Rigorous upper bounds and partial evidence relative to the strongest displayed classical algorithms in their respective graph classes.
\dimensionlabel{Hardware}{hardwareExponential} The general algorithm needs polynomial active registers and exponential QRAM. The bounded-degree versions need polynomial logical workspace but exponentially long coherent tree searches. Both useful regimes require fault tolerance; degree restrictions reduce the exponential time base.
\subhead{Algorithm}
\begin{algorithmindex}{7}
\item \href{https://arxiv.org/pdf/1807.05209}{Ambainis et al., \emph{Quantum Speedups for Exponential-Time Dynamic Programming Algorithms} (SODA 2019)}. Theorem 8 and Algorithm 2; the TSP section states the classical Held--Karp recurrence.
\item \href{https://arxiv.org/pdf/1612.06203}{Moylett, Linden and Montanaro, \emph{Quantum Speedup of the Traveling-Salesman Problem for Bounded-Degree Graphs} (2017)}. Theorem 1; Theorems 4--5 give the degree-three and degree-four algorithms and their classical search subroutines.
\item \href{https://serggasp.github.io/pathwidth-site/papers/sparse-pathwidth/14-apps-connectivity.html}{Gaspers, \emph{Path Decompositions of Sparse Graphs via Gaussian Sweeps and Faster Exponential Algorithms} (2026)}. Theorem 14.1(d): weighted TSP applications.
